import React, { useEffect, useState } from "react";

import { getStore, updStore, gen16CodeId, hasWritePrivilege, parseDateMMDDYYYY, AccountYears } from "../../../stores/Utils";

import "./dashboard.css"
import {  ViewMovement_Cmpt } from "..";
import { OpenModal } from "../../../components/DialogHRM";
import { getall_movement, loadCSVInve, sortProducts } from "../services/server_fetching";
import { SvgIcon_Cmpt } from "../../../components";
import DeleteAlert from "./deleteAlert";
import NoPrivilege from "./NoPrivilege";


const Svg = SvgIcon_Cmpt();


const ViewMovement = ViewMovement_Cmpt();


const MovementItem  = ({ data, handleRefreshAll }) => {
	const [initialize, setInitialize] = useState(false);
	const [_, set_obs] = useState(0);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			
			set_obs(gen16CodeId())
		}
	}, [initialize]);

	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	const refreshAccs =  () => {
		getall_movement(updObs)
	}

	const update = async () => {
		//loadCSVInve()
	}

	
	const openSubMayor =  (sba) => {
		updStore("view_product_entry_comprobante", data);
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true };
		modaldata["content"] = 
			<ViewMovement confirm={refreshAccs} item={data}/>
		OpenModal(modaldata);
	}


	const deleteComprobante =  () => {
		// delete_movement(data?.entriesInvoiceId, handleRefreshAll);
	}
	

	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(hasWritePrivilege()){
			if( Date.now() > lastTimeCallModal){
				updStore("lastTimeCallModal", Date.now()+320);
				let modaldata = {};
				modaldata["zIndex"] = 450;
				modaldata["height"] = "40vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
				modaldata["content"] = <DeleteAlert label={"Eliminar Movimiento"} confirm={deleteComprobante} item={data} />
				OpenModal(modaldata);
			}
		}else{
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <NoPrivilege />
			OpenModal(modaldata);
		}
	}

	

	let subAcc = sortProducts( getStore("sub_movement_group")?.[data.movementId],"subProduct");
	

	return (
		<div className="item_acc">
			<div className="_dsplFlx item_box movement_header">
				<div className="_dsplFlx  tr_bar tr_bar_70"  onClick={update}>
					<div className="name tr_bar tr_bar_30" >
						{parseDateMMDDYYYY(data?.date)} 
					</div>
					<div className="code tr_bar tr_bar_25" style={{marginLeft:14}}>
						{data?.comprobanteId}
					</div>
					<div className="code tr_bar tr_bar_20" style={{marginLeft:14, textAlign: "right", color:data?.amount<0?"#c62828":""}}>
						{(data?.amount*1).toFixed(2)}
					</div>
					<div className="cod tr_bar tr_bar_40" style={{marginLeft:14}}>
					{data?.document}
					</div>
				</div>
				<div className="flexSpace"/>
				<div className=" addSbAcc purple" onClick={()=>openSubMayor(null)}>
					Details
				</div>
				{hasWritePrivilege()?
				AccountYears()[getStore("date_current_year")]?.isClosed?null:
				<div className="icon" style={{marginLeft: 19}} onClick={OpenDeleteAlert}>
					<Svg name={"outline_delete"} color={"#c62828"}/>
				</div>
				:null}
			</div>
		</div>
	)
}
export default MovementItem;





